import { seedLifecycleFixture, lifecycleAt, lifecycleActor } from "./procurement-lifecycle.js";
import { createAuditService } from "../../src/services/audit.service.js";
import { createMemoryRepository } from "../../src/repositories/memory.js";
import { createProcurementLifecycleService } from "../../src/services/procurement-lifecycle.service.js";
import { createProcurementPaymentsService } from "../../src/services/procurement-payments.service.js";
import { createProcurementProgressService } from "../../src/services/procurement-progress.service.js";
import { createProcurementInspectionsService } from "../../src/services/procurement-inspections.service.js";
import { createProcurementHandoverService } from "../../src/services/procurement-handover.service.js";
import { createProcurementReadinessService } from "../../src/services/procurement-readiness.service.js";
import { createLifecycleFindingBridge } from "../../src/services/procurement-lifecycle/findings-bridge.js";
import { procurementItemSourceSnapshot } from "../../src/services/procurement.service.js";
import { readPaymentCertificationSource } from "../../src/services/project-manager/vendors.js";
import { basketQualityDigest } from "../../src/services/ai-estimator-knowledge-basket-quality.js";
import { lcTransaction } from "../../src/services/procurement-lifecycle/transaction.js";
import { UserModel } from "../../src/models/User.js";
import { ProjectPurchaseOrderModel } from "../../src/models/ProjectPurchaseOrder.js";
import { ProjectPurchaseOrderRevisionModel } from "../../src/models/ProjectPurchaseOrderRevision.js";
import { ProcurementBasketAwardModel, ProcurementBasketAwardRevisionModel } from "../../src/models/ProcurementBasketTender.js";
import { ProcurementBasketInvoiceAssessmentModel, ProcurementBasketInvoiceAssessmentRevisionModel } from "../../src/models/ProcurementBasketInvoiceAssessment.js";
import { ProjectPaymentCertificationModel } from "../../src/models/ProjectPaymentCertification.js";
import { ProcurementLifecycleEvidenceModel } from "../../src/models/ProcurementLifecycleEvidence.js";
import { AiEstimatorKnowledgeBasketModel } from "../../src/models/AiEstimatorKnowledgeBasket.js";
import { AiEstimatorKnowledgeBasketQualityRevisionModel } from "../../src/models/AiEstimatorKnowledgeBasketQualityRevision.js";
import { SiteCompletionStateModel } from "../../src/models/SiteCompletionState.js";
import { SiteCompletionReviewModel } from "../../src/models/SiteCompletionReview.js";

/** Real lifecycle commands over synthetic issued/certified/accepted source records. */
export async function seedReadyProcurement(suffix = "ready") {
  const f = await seedLifecycleFixture(suffix); let at = new Date(lifecycleAt); let serial = 0;
  const key = () => `ready-${suffix}-${++serial}`;
  const deps = { audit: createAuditService(createMemoryRepository()), now: () => at };
  const findingDeps = { ...deps, createFindingInSession: createLifecycleFindingBridge(deps) };
  const lifecycle = createProcurementLifecycleService(deps), payments = createProcurementPaymentsService(deps), progress = createProcurementProgressService(deps), inspections = createProcurementInspectionsService({ ...findingDeps, random: () => 0 }), handover = createProcurementHandoverService(findingDeps), readiness = createProcurementReadinessService(deps);
  const admin = lifecycleActor("sole-ready-admin", "super_admin");
  await UserModel.collection.updateOne({ _id: admin.id }, { $setOnInsert: { ...admin, active: true } }, { upsert: true });
  const source = await lcTransaction(s => procurementItemSourceSnapshot(f.projectId, s));
  const lineage = { estimateId: source.estimateId, estimateVersion: source.estimateVersion, estimateReviewRoundId: source.estimateReviewRoundId };
  const awardId = `${f.orderId}-award`, proposalId = `${awardId}-proposal`, assessmentId = `${f.orderId}-assessment`, assessmentRevisionId = `${assessmentId}-revision`;
  await ProjectPurchaseOrderModel.collection.updateOne({ _id: f.orderId }, { $set: { tenderAwardId: awardId, approvedNetPaise: 60000, approvedGstPaise: 0, version: 1 } });
  await ProjectPurchaseOrderRevisionModel.collection.updateOne({ _id: f.revisionId }, { $set: { ...lineage, tenderAwardId: awardId, totalPaise: 60000, netPaise: 60000, gstPaise: 0, "lines.$[].estimateId": lineage.estimateId, "lines.$[].estimateVersion": lineage.estimateVersion, "lines.$[].estimateReviewRoundId": lineage.estimateReviewRoundId } });
  const milestones = [{ id: "final", name: "Final", amountPaise: 60000, reviewerSlots: ["procurement"] }];
  await ProcurementBasketAwardModel.collection.insertOne({ _id: awardId, projectId: f.projectId, status: "issued", issuedPurchaseOrderId: f.orderId, currentProposalRevisionId: proposalId } as any);
  await ProcurementBasketAwardRevisionModel.collection.insertOne({ _id: proposalId, awardId, projectId: f.projectId, vendorId: f.vendorId, milestones } as any);
  await ProcurementBasketInvoiceAssessmentModel.collection.insertOne({ _id: assessmentId, projectId: f.projectId, orderId: f.orderId, currentRevisionId: assessmentRevisionId } as any);
  await ProcurementBasketInvoiceAssessmentRevisionModel.collection.insertOne({ _id: assessmentRevisionId, assessmentId, projectId: f.projectId, orderId: f.orderId, awardId, invoiceTotalPaise: 60000, tdsPaise: 0, netPayablePaise: 60000 } as any);
  const certSource = await lcTransaction(s => readPaymentCertificationSource(f.projectId, f.orderId, "final", s));
  await ProjectPaymentCertificationModel.collection.insertOne({ _id: `${f.orderId}-cert`, projectId: f.projectId, orderId: f.orderId, orderRevisionId: f.revisionId, proposalRevisionId: proposalId, milestoneId: "final", amountPaise: 60000, sourceToken: certSource.token, status: "certified" } as any);
  const basketId = `${f.projectId}-basket`, qualityId = `${basketId}-quality`;
  const parameter = { id: "secure", type: "checkbox", label: "Fixings secure", required: true, active: true, evidence: { photos: false, documents: false, video: false, minPhotosPerSample: null } };
  await AiEstimatorKnowledgeBasketModel.collection.insertOne({ _id: basketId, name: "Interiors", status: "active", version: 1, dependencyEpoch: 0, qualityRevisionId: qualityId } as any);
  await AiEstimatorKnowledgeBasketQualityRevisionModel.collection.insertOne({ _id: qualityId, basketId, revisionNumber: 1, parameters: [parameter], contentDigest: basketQualityDigest(basketId, [parameter]), createdAt: at } as any);
  const before = await lifecycle.get(f.buyer, f.projectId);
  await lifecycle.setup(f.buyer, f.projectId, { expectedVersion: 0, sourceDigest: before.sourceDigest, idempotencyKey: key(), policy: { timezone: "Asia/Kolkata", reviewIntervalDays: 7, inspectionCount: 2 }, reason: "Adopt approved project execution" });
  async function payment(input: Record<string, unknown>, actor = f.finance) { const current = (await payments.list(actor, f.projectId)).items[0]!; return payments.command(actor, f.projectId, { orderId: f.orderId, expectedVersion: current.version, sourceDigest: current.sourceDigest, idempotencyKey: key(), ...input }); }
  await payment({ action: "reconcile", reconciliationId: `${f.projectId}-opening`, openingBalances: [{ milestoneId: "final", amountPaise: 0 }], evidenceIds: [], reason: "Confirmed no previous bank payments" });
  await payment({ action: "confirm_dates", dates: [{ milestoneId: "final", dueDate: "2026-11-27" }], reason: "Agreed completion payment date" });
  await payment({ action: "authorize", basis: "invoice", assessmentRevisionId, allocations: [{ milestoneId: "final", grossPaise: 60000, withholdingPaise: 0, netPaise: 60000 }], reason: "Approved assessed invoice" });
  const transactionId = `${f.projectId}-transfer`;
  const evidence = async (id: string, entityId: string, purpose: string, kind: string) => ProcurementLifecycleEvidenceModel.collection.insertOne({ _id: id, projectId: f.projectId, entityId, purpose, kind, uploaderId: f.buyer.id, originalFilename: "synthetic", mimeType: kind === "document" ? "application/pdf" : "image/jpeg", storageReference: `opaque-${id}`, byteSize: 1, sha256: "0".repeat(64), referenceEpoch: 0, createdAt: at } as any);
  await evidence(`${transactionId}-proof`, transactionId, "payment", "document");
  await payment({ action: "record", transactionId, amountPaise: 60000, allocations: [{ milestoneId: "final", amountPaise: 60000 }], paidAt: at.toISOString(), method: "bank_transfer", reference: transactionId, evidenceIds: [`${transactionId}-proof`] }, f.buyer);
  let round = (await progress.list(f.buyer, f.projectId)).current!;
  for (const member of round.members) round = await progress.command(f.buyer, f.projectId, { expectedVersion: round.version, sourceDigest: round.currentSourceDigest, roundId: round.id, idempotencyKey: key(), action: "check", itemId: member.item.id, observation: { checkedAt: at.toISOString(), status: "completed", progress: 100, notes: "Inspected completed work", nextAction: "Review project handover", nextCheckDate: "2026-11-28", delayed: false } });
  await progress.command(f.buyer, f.projectId, { expectedVersion: round.version, sourceDigest: round.currentSourceDigest, roundId: round.id, idempotencyKey: key(), action: "finalize", notes: "All priority groups reviewed" });
  const summary = await lifecycle.get(f.buyer, f.projectId);
  let plan = await inspections.plan(f.buyer, f.projectId, { expectedVersion: 0, sourceDigest: summary.sourceDigest, idempotencyKey: key(), count: 2, windows: [1,3].map(minute => ({ id: `${f.projectId}-slot-${minute}`, startsAt: new Date(at.getTime() + minute*60000).toISOString(), endsAt: new Date(at.getTime() + (minute+1)*60000).toISOString() })), reason: "Two independent project inspections" });
  at = new Date(at.getTime() + 5*60000);
  for (const slot of plan.plan!.slots) await inspections.record(f.buyer, f.projectId, { expectedVersion: plan.plan!.version, sourceDigest: summary.sourceDigest, idempotencyKey: key(), visitId: `${slot.id}-visit`, slotId: slot.id, inspectedAt: slot.plannedAt, itemIds: summary.source.items.map(item => item.id), notes: "Physical inspection completed with no findings", delayed: false, evidenceIds: [], findings: [] });
  let panel = await handover.get(f.buyer, f.projectId);
  const photo = `${f.projectId}-photo`, document = `${f.projectId}-document`;
  await evidence(photo, panel.evidenceEntityId, "handover", "image"); await evidence(document, panel.evidenceEntityId, "handover", "document");
  panel = await handover.command(f.buyer, f.projectId, { expectedVersion: panel.version, sourceDigest: panel.sourceDigest, idempotencyKey: key(), action: "save", answers: panel.checks.map(check => ({ checkId: check.id, answer: check.required ? "pass" : "not_applicable", note: check.required ? "Inspected and accepted" : "No applicable equipment for this scope", sampleCount: 1, evidenceIds: !check.required ? [] : check.evidence?.photos ? [photo] : check.evidence?.documents ? [document] : [] })) });
  await handover.command(f.buyer, f.projectId, { expectedVersion: panel.version, sourceDigest: panel.sourceDigest, idempotencyKey: key(), action: "submit", reason: "Procurement handover verified" });
  const reviewId = `${f.projectId}-site-acceptance`;
  await SiteCompletionStateModel.collection.insertOne({ _id: f.projectId, projectId: f.projectId, currentRound: 1, progress: 100, version: 3, status: "client_approved" } as any);
  await SiteCompletionReviewModel.collection.insertOne({ _id: reviewId, projectId: f.projectId, ...lineage, round: 1, clientId: f.client.id, managerId: f.manager.id, status: "approved", decision: { decision: "approve", actorId: f.client.id }, approvedRevisionIds: [f.revisionId], sourceLineItemKeys: source.lineItems.map(line => line.key), sections: summary.source.items.map(item => ({ assignmentId: item.id })) } as any);
  const ready = await readiness.get(f.buyer, f.projectId);
  const submitted = await readiness.command(f.buyer, f.projectId, { expectedVersion: ready.version, sourceDigest: ready.sourceDigest, idempotencyKey: key(), action: "submit", reason: "All Procurement obligations checked" });
  return { ...f, admin, deps, payment, payments, handover, readiness, submitted, transactionId, now: () => at, key };
}
